CREATE TABLE public.cheque_reminders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),branch_id text NOT NULL REFERENCES public.branches(id),sale_id uuid REFERENCES public.sales(id),payment_id uuid REFERENCES public.loan_payments(id),cheque_number text NOT NULL,cheque_date date NOT NULL,amount numeric(16,2) NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),deposited_at timestamptz,deposited_by uuid);
GRANT SELECT ON public.cheque_reminders TO authenticated;GRANT ALL ON public.cheque_reminders TO service_role;
ALTER TABLE public.cheque_reminders ENABLE ROW LEVEL SECURITY;
CREATE POLICY cheques_read ON public.cheque_reminders FOR SELECT TO authenticated USING(public.staff_can('Create bills',branch_id) OR public.staff_can('Collect repayments',branch_id) OR public.staff_can('View reports',branch_id));
CREATE FUNCTION public.capture_cheque_payment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p jsonb;method text;a numeric;BEGIN IF TG_TABLE_NAME='sales' THEN method:=NEW.payment_method;a:=NEW.paid_now;ELSE method:=NEW.method;a:=NEW.amount;END IF;IF method<>'Cheque' OR a<=0 THEN RETURN NEW;END IF;p:=nullif(current_setting('app.cheque_payment',true),'')::jsonb;IF nullif(trim(p->>'cheque_number'),'') IS NULL OR p->>'cheque_date' IS NULL THEN RAISE EXCEPTION 'Cheque number and deposit date are required';END IF;INSERT INTO public.cheque_reminders(branch_id,sale_id,payment_id,cheque_number,cheque_date,amount,created_by) VALUES(NEW.branch_id,CASE WHEN TG_TABLE_NAME='sales' THEN NEW.id ELSE NULL END,CASE WHEN TG_TABLE_NAME='loan_payments' THEN NEW.id ELSE NULL END,trim(p->>'cheque_number'),(p->>'cheque_date')::date,a,auth.uid());RETURN NEW;END $$;
CREATE TRIGGER capture_sale_cheque AFTER INSERT ON public.sales FOR EACH ROW EXECUTE FUNCTION public.capture_cheque_payment();
CREATE TRIGGER capture_repayment_cheque AFTER INSERT ON public.loan_payments FOR EACH ROW EXECUTE FUNCTION public.capture_cheque_payment();
DO $$ DECLARE fn text;d text;BEGIN FOREACH fn IN ARRAY ARRAY['complete_sale','record_payment'] LOOP SELECT pg_get_functiondef(('public.'||fn||'(jsonb)')::regprocedure) INTO d;d:=replace(d,'PERFORM set_config(''app.branch_id'',b,true);','PERFORM set_config(''app.branch_id'',b,true); PERFORM set_config(''app.cheque_payment'',p::text,true);');EXECUTE d;END LOOP;FOREACH fn IN ARRAY ARRAY['internal_complete_sale','internal_record_payment'] LOOP SELECT pg_get_functiondef(('public.'||fn||'(jsonb)')::regprocedure) INTO d;d:=replace(d,'''Bank Transfer'',''Mixed''','''Bank Transfer'',''Mixed'',''Cheque''');EXECUTE d;END LOOP;END $$;
CREATE FUNCTION public.deposit_cheque(cid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.cheque_reminders;BEGIN SELECT * INTO c FROM public.cheque_reminders WHERE id=cid FOR UPDATE;IF NOT FOUND OR NOT (public.staff_can('Create bills',c.branch_id) OR public.staff_can('Collect repayments',c.branch_id)) THEN RAISE EXCEPTION 'Payment permission required';END IF;IF c.deposited_at IS NOT NULL THEN RAISE EXCEPTION 'Cheque already marked deposited';END IF;IF c.cheque_date>(now() AT TIME ZONE 'Asia/Colombo')::date THEN RAISE EXCEPTION 'Cheque deposit date has not arrived';END IF;UPDATE public.cheque_reminders SET deposited_at=now(),deposited_by=auth.uid() WHERE id=cid;INSERT INTO public.audit_events(actor_id,actor_name,branch_id,category,action,description,record_id) VALUES(auth.uid(),coalesce((SELECT display_name FROM public.profiles WHERE id=auth.uid()),'Staff'),c.branch_id,'Cheques','Deposited','Marked cheque '||c.cheque_number||' as deposited',cid::text);END $$;
REVOKE ALL ON FUNCTION public.deposit_cheque(uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.deposit_cheque(uuid) TO authenticated;